import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.DSoq407f.js";const k=JSON.parse('{"title":"Docker 部署","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/docker.md","filePath":"deploy/docker.md","lastUpdated":1786505997000}'),l={name:"deploy/docker.md"};function o(n,a,r,c,d,p){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="docker-部署" tabindex="-1">Docker 部署 <a class="header-anchor" href="#docker-部署" aria-label="Permalink to &quot;Docker 部署&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：用一键脚本把 V3 跑起来。</p></blockquote><p>V3 提供<strong>一键部署脚本</strong> <code>install.sh</code>，封装了加载镜像、配置端口、启动容器、健康检查的全流程，无需懂 Docker 命令。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已安装 Docker Engine 24+ 和 Docker Compose v2。</li><li>已准备好 PostgreSQL 数据库（<a href="./requirements">环境要求</a>）。</li><li>已拿到 V3 发布包（含镜像 tar 和部署文件）。</li></ul><div class="tip custom-block"><p class="custom-block-title">验证 Docker</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 应显示 24+</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 应显示 v2.x</span></span></code></pre></div></div><h2 id="一键部署" tabindex="-1">一键部署 <a class="header-anchor" href="#一键部署" aria-label="Permalink to &quot;一键部署&quot;">​</a></h2><p>解压发布包后，目录里会有 <code>install.sh</code>。执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>脚本会依次完成：</p><ol><li><strong>检查环境</strong> —— 确认 Docker / Compose 已安装。</li><li><strong>加载镜像</strong> —— <code>docker load</code> 导入 V3 镜像 tar 包。</li><li><strong>配置端口</strong> —— 询问你要暴露的端口（默认 8000）。</li><li><strong>启动容器</strong> —— <code>docker compose up -d</code>。</li><li><strong>健康检查</strong> —— 轮询 <code>/api/health</code> 直到服务就绪。</li></ol><p>脚本结束后会提示访问地址。</p><h2 id="端口映射说明" tabindex="-1">端口映射说明 <a class="header-anchor" href="#端口映射说明" aria-label="Permalink to &quot;端口映射说明&quot;">​</a></h2><p>容器内部固定监听 <code>8000</code>。你在脚本里填的端口是<strong>宿主机端口</strong>，映射关系是 <code>宿主机端口:8000</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的端口 8000  →  容器内 8000</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">配合 Nginx</p><p>生产环境建议让 V3 只监听本地（<code>127.0.0.1:端口</code>），由 Nginx 反代到公网。这样更安全，也方便配 HTTPS。详见 <a href="./nginx">Nginx 反向代理</a>。</p></div><h2 id="首次安装" tabindex="-1">首次安装 <a class="header-anchor" href="#首次安装" aria-label="Permalink to &quot;首次安装&quot;">​</a></h2><p>容器启动后，浏览器访问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://服务器IP:端口/install</span></span></code></pre></div><p>按 <a href="./install">安装向导</a> 填写数据库连接、创建管理员、自动获取授权码。</p><h2 id="升级部署" tabindex="-1">升级部署 <a class="header-anchor" href="#升级部署" aria-label="Permalink to &quot;升级部署&quot;">​</a></h2><p>发布新版本时，把新的发布包覆盖到部署目录，再跑一次 <code>install.sh</code>：</p><ul><li>脚本会自动停掉旧容器、启动新容器。</li><li>数据在 volume 里持久化，<strong>不会丢失</strong>。</li></ul><div class="warning custom-block"><p class="custom-block-title">在线更新 vs 重新部署</p><ul><li>小版本更新：用后台「在线更新」即可，无需重新部署（见 <a href="./update">在线更新</a>）。</li><li>大版本 / 镜像变更：重新跑 <code>install.sh</code> 覆盖部署。</li></ul></div><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>部署包附带 <code>uninstall.sh</code>，支持多级别清理（只停容器 / 删数据 / 彻底删除）。详见 <a href="./ops#卸载">运维与备份</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>走安装向导 → <a href="./install">安装向导</a></li><li>配 HTTPS 反代 → <a href="./nginx">Nginx 反向代理</a></li></ul>`,28)])])}const u=s(l,[["render",o]]);export{k as __pageData,u as default};
